CREATE OR REPLACE FUNCTION public.get_my_profile() RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r JSONB; BEGIN SELECT jsonb_build_object('id_number',u.id_number,'username',u.username,'email',u.email,'role',u.role,'first_name',p.first_name,'middle_initial',p.middle_initial,'last_name',p.last_name,'suffix',p.suffix,'birthdate',p.birthdate,'age',p.age,'sex',p.sex,'position',p.position) INTO r FROM users u LEFT JOIN profiles p ON p.user_id=u.id WHERE u.id=auth.uid(); RETURN r; END; $$;
CREATE OR REPLACE FUNCTION public.update_my_profile(p_id_number TEXT,p_username TEXT,p_email TEXT,p_role TEXT,p_first_name TEXT,p_middle_initial TEXT,p_last_name TEXT,p_suffix TEXT,p_birthdate DATE,p_age INT,p_sex TEXT,p_position TEXT,p_password TEXT DEFAULT NULL) RETURNS BOOLEAN LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM users WHERE id=auth.uid()) THEN RAISE EXCEPTION 'Not authenticated'; END IF; UPDATE auth.users SET email=p_email, encrypted_password=CASE WHEN p_password IS NULL OR p_password='' THEN encrypted_password ELSE crypt(p_password,gen_salt('bf')) END WHERE id=auth.uid(); UPDATE users SET id_number=p_id_number,username=p_username,email=p_email WHERE id=auth.uid(); UPDATE profiles SET first_name=p_first_name,middle_initial=NULLIF(p_middle_initial,''),last_name=p_last_name,suffix=NULLIF(p_suffix,''),birthdate=p_birthdate,age=p_age,sex=p_sex,position=NULLIF(p_position,'') WHERE user_id=auth.uid(); RETURN TRUE; END; $$;
